import { describe, expect, it, vi } from 'vitest';
import { exportProject, parseProjectFile } from '../core/exportFile';
import { mockFromLog } from '../core/record';
import { mergeProject } from '../core/scenarioOps';
import { BODY_CAP_BYTES, newProject, type LogDraft, type LogEntry, type Mock, type Project, type Settings, type SocketMock } from '../core/types';
import { installFetchPatch, type PatchDeps } from './fetchPatch';
import { createGate } from './gate';

const ids = () => {
  let n = 0;
  return () => `n${++n}`;
};

describe('#7 Add gives socket replies and pushes new ids', () => {
  const sock = (): SocketMock => ({
    id: 's', enabled: true, kind: 'signalr', urlPattern: '/hub', createdAt: 0,
    onConnect: [{ id: 'p0', afterMs: 0, target: 'A', data: '[]' }],
    replies: [{ id: 'r1', when: 'X', respond: 'code', result: '', code: 'return 1', pushes: [{ id: 'p1', afterMs: 0, target: 'B', data: '[]' }] }],
  });
  it('every id under an added socket is new', () => {
    const target = newProject('t', 'http://a.test');
    target.scenarios[0]!.sockets = [sock()];
    const incoming: Project = { ...newProject('i', 'http://a.test') };
    incoming.scenarios[0]!.sockets = [sock()];
    incoming.scenarios.push({ id: 'x', name: 'X', mocks: [], sockets: [sock()] });
    const m = mergeProject(target, incoming, ids());
    const all = m.scenarios.flatMap((s) => (s.sockets ?? []).flatMap((k) => [k.id, ...k.onConnect.map((p) => p.id), ...k.replies.flatMap((r) => [r.id, ...r.pushes.map((p) => p.id)])]));
    expect(new Set(all).size).toBe(all.length);
  });
  it('a file with duplicate reply ids loads with unique ones', () => {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.sockets = [sock(), { ...sock(), id: 's2' }];
    const r = parseProjectFile(exportProject(p));
    if (!r.ok) throw new Error(r.error);
    const replyIds = r.project.scenarios[0]!.sockets!.flatMap((k) => k.replies.map((x) => x.id));
    expect(new Set(replyIds).size).toBe(2);
  });
});

describe('#6 a base64 body that is not base64 is refused at import', () => {
  it('rejects the file', () => {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.mocks.push({
      id: 'm', enabled: true, method: 'GET', urlPattern: '/x', source: 'manual', createdAt: 0,
      response: { status: 200, headers: {}, body: '!!', bodyEncoding: 'base64', delayMs: 0 },
    });
    expect(parseProjectFile(exportProject(p)).ok).toBe(false);
  });
});

describe('#13 a custom method is recorded as ANY', () => {
  it('PROPFIND becomes ANY, GET stays GET', () => {
    const e = (method: string): LogEntry => ({
      id: 'l', method, url: 'http://a.test/dav', status: 207, responseHeaders: {}, responseBody: '', responseEncoding: 'text',
      truncated: false, durationMs: 1, badge: 'real', startedAt: 1,
    });
    expect(mockFromLog(e('PROPFIND'), 'm', 1).method).toBe('ANY');
    expect(mockFromLog(e('get'), 'm', 1).method).toBe('GET');
  });
});

function testWin(response: () => Response) {
  const nativeFetch = vi.fn(async () => response());
  const win = { fetch: nativeFetch, Request, Response, Headers, location: { href: 'https://app.test/page' } } as unknown as Window;
  return { win, nativeFetch };
}
function deps(settings: Settings, mocks: Mock[] = []) {
  const gate = createGate();
  gate.open({ mocks, settings });
  const reported: LogDraft[] = [];
  const d: PatchDeps = { gate, report: (x) => reported.push(x), now: () => 0 };
  return { d, reported };
}
/** A body the page never reads; counts how many chunks anyone pulled from it. */
function countingBody(chunkBytes: number, chunks: number) {
  let pulled = 0;
  const body = new ReadableStream<Uint8Array>({
    pull(c) {
      if (pulled >= chunks) { c.close(); return; }
      pulled++;
      c.enqueue(new Uint8Array(chunkBytes).fill(65));
    },
  });
  return { body, pulled: () => pulled };
}

describe('#9 real bodies are not buffered without need', () => {
  it('with recording off, wemock reads nothing of a real body', async () => {
    const b = countingBody(64 * 1024, 1_000_000);
    const { win } = testWin(() => new Response(b.body, { headers: { 'content-type': 'text/plain' } }));
    const { d, reported } = deps({ enabled: true, recording: false });
    installFetchPatch(win, d);
    const res = await win.fetch('https://app.test/stream');
    expect(res.status).toBe(200);
    await new Promise((r) => setTimeout(r, 100));
    expect(b.pulled()).toBeLessThan(5);
    expect(reported).toEqual([]);
  });
  it('with recording on, wemock stops reading at the cap and logs the row as truncated', async () => {
    const b = countingBody(64 * 1024, 1_000_000);
    const { win } = testWin(() => new Response(b.body, { headers: { 'content-type': 'text/plain' } }));
    const { d, reported } = deps({ enabled: true, recording: true });
    installFetchPatch(win, d);
    await win.fetch('https://app.test/stream');
    await vi.waitFor(() => expect(reported).toHaveLength(1), { timeout: 3000 });
    expect(reported[0]).toMatchObject({ truncated: true, responseBody: null });
    expect(b.pulled() * 64 * 1024).toBeLessThan(BODY_CAP_BYTES * 3);
  });
});

describe('#12 an abort rejects with the signal\'s reason', () => {
  it('a delayed mock aborted by a timeout rejects with TimeoutError', async () => {
    const mock: Mock = {
      id: 'm', enabled: true, method: 'ANY', urlPattern: '/slow', source: 'manual', createdAt: 0,
      response: { status: 200, headers: {}, body: 'x', bodyEncoding: 'text', delayMs: 2000 },
    };
    const { win } = testWin(() => new Response('real'));
    const { d } = deps({ enabled: true, recording: true }, [mock]);
    installFetchPatch(win, d);
    const ac = new AbortController();
    const p = win.fetch('https://app.test/slow', { signal: ac.signal });
    setTimeout(() => ac.abort(new DOMException('took too long', 'TimeoutError')), 20);
    await expect(p).rejects.toMatchObject({ name: 'TimeoutError' });
    const ac2 = new AbortController();
    const p2 = win.fetch('https://app.test/slow', { signal: ac2.signal });
    setTimeout(() => ac2.abort(), 20);
    await expect(p2).rejects.toMatchObject({ name: 'AbortError' });
  });
});
